def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    strong_threat = 0
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(bid)
                if bid >= 85:
                    strong_threat += 1

    if not alive:
        return min(budget, 18.0)

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    urgency = 0
    if hp <= 2:
        urgency += 4
    elif hp <= 4:
        urgency += 3
    elif hp <= 6:
        urgency += 2
    else:
        urgency += 1

    if no_water_days >= 2:
        urgency += 3
    elif no_water_days >= 1:
        urgency += 1

    if supply <= 16:
        urgency += 3
    elif supply <= 19:
        urgency += 2
    else:
        urgency += 1

    if day >= 8:
        urgency += 1

    if budget <= 70:
        urgency += 1

    if urgency >= 8:
        bid = max(92.0, highest_prev + 2.0)
    elif urgency >= 6:
        bid = max(72.0, avg_prev * 0.9)
    elif urgency >= 4:
        if highest_prev >= 110:
            bid = 38.0
        else:
            bid = max(48.0, min(78.0, highest_prev * 0.7 + 4.0))
    else:
        if strong_threat >= 2:
            bid = 16.0
        elif highest_prev >= 90:
            bid = 22.0
        else:
            bid = 28.0

    if hp <= 2 or no_water_days >= 2:
        bid = max(bid, 95.0)

    if supply >= 23 and hp >= 7 and no_water_days == 0:
        bid = min(bid, 24.0)

    if day == 1 and hp >= 7:
        bid = min(bid, 30.0)

    return min(budget, max(0.0, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return 0

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if not yesterday_bids:
        return min(my_status['budget'], DAILY_SALARY * 0.6)

    avg_opp_bid = sum(yesterday_bids) / len(yesterday_bids)

    if my_status['hp'] < 4:
        return min(my_status['budget'], avg_opp_bid * 1.1)

    if day_context['supply'] < WATER_REQ * 2:
        return min(my_status['budget'], avg_opp_bid * 1.05)

    return min(my_status['budget'], avg_opp_bid * 0.95)
